import React from "react";
import { Tile } from "../tile"

export const TileList = ({items}) => {
  return (
    <div>
      {items.map(({name, ...rest}, index) => {
          <Tile 
            name={name}
            key={index}
            description={rest}
          />
      })}
    </div>
  );
};
